const TZ = 'America/Sao_Paulo';
const fmtFone = (n) => { const d = String(n || '').replace(/\D/g, ''); if (d.length >= 12 && d.startsWith('55')) { const r = d.slice(2); return `+55 (${r.slice(0,2)}) ${r.slice(2, r.length-4)}-${r.slice(-4)}`; } return '+' + d; };
const fmtData = (iso) => DateTime.fromISO(String(iso), { zone: TZ }).setZone(TZ).setLocale('pt-BR').toFormat("cccc, dd/MM/yyyy 'às' HH:mm");

const d = $input.first().json;
if (!d.responsavel) return [{ json: { sem_responsavel: true, resposta: 'Não há ninguém da equipe cadastrado para receber o atendimento. Informe ao cliente que a equipe retornará pelo telefone ' + (d.escritorio?.telefone || 'do escritório') + '.' } }];
const r = d.responsavel, l = d.lead, e = d.escritorio;
const nome = l.nome || l.nome_whatsapp || 'Cliente';
const icone = { alta: '🔴 ALTA', media: '🟡 média', baixa: '🟢 baixa' }[d.urgencia] || d.urgencia;
const ultimas = d.ultimas_mensagens ? d.ultimas_mensagens.split('\n').reverse().join('\n') : '';
const texto = [
  `🔔 *Atendimento encaminhado para você*`, `*Urgência:* ${icone}`, '',
  `*Cliente:* ${nome}${l.ja_e_cliente ? ' (já é cliente)' : ''}`,
  `*WhatsApp:* ${fmtFone(l.whatsapp)} (wa.me/${l.whatsapp})`,
  `*Área:* ${d.area || l.area || '-'}`,
  `*Motivo:* ${d.motivo || '-'}`,
  `*Resumo:* ${d.resumo || l.resumo_caso || '-'}`,
  ...(ultimas ? ['', '*Últimas mensagens:*', ultimas] : []), '',
  `_A assistente virtual foi pausada nesta conversa por ${e.horas_pausa_ia}h. Responda o cliente pelo WhatsApp do escritório ou pelo Chatwoot. Para reativar a IA antes, envie #ia na conversa ou resolva a conversa no Chatwoot._`,
].join('\n');

// dentro do horário de atendimento?
const agora = DateTime.now().setZone(TZ);
const nomesDia = [null, 'seg', 'ter', 'qua', 'qui', 'sex', 'sab', 'dom'];
let faixas = e.horario_atendimento?.[nomesDia[agora.weekday]] || [];
if (faixas.length && !Array.isArray(faixas[0])) faixas = [faixas];
const hhmm = agora.toFormat('HH:mm');
const noHorario = faixas.some(([a, b]) => hhmm >= a && hhmm < b);
const primeiroNome = r.nome;
const resposta = noHorario || d.urgencia === 'alta'
  ? `Encaminhado para ${primeiroNome}, que já recebeu o contato e o resumo e vai responder por aqui em breve. Avise o cliente.`
  : `Encaminhado para ${primeiroNome}. Agora está fora do horário de atendimento da equipe; avise o cliente que o retorno será no próximo horário de atendimento.`;
return [{ json: {
  instancia: e.instancia_whatsapp, numero: r.whatsapp, texto, encaminhamento_id: d.encaminhamento_id,
  contato: { fullName: nome, wuid: l.whatsapp, phoneNumber: '+' + l.whatsapp }, resposta,
}}];
